        setText(status, L["Sending..."])
        task.spawn(function()
            local ok, err = send(tostring(val("FeedbackType", "Suggestion")):lower(), msg)
            if ok then last = tick(); setText(status, L["Sent. Thank you!"]); pcall(function() Opt.FeedbackMsg:SetValue("") end)
