do
    local CAS = game:GetService("ContextActionService")
    local fc = { on = false }
    local Kc = Enum.KeyCode
    local keys = { Kc.W, Kc.A, Kc.S, Kc.D, Kc.Q, Kc.E, Kc.Space, Kc.LeftShift, Kc.Up, Kc.Down, Kc.Left, Kc.Right }
    local function stop()
        if not fc.on then return end
        fc.on = false
        pcall(function() CAS:UnbindAction("CW_Freecam") end)
        pcall(function() UserInputService.MouseBehavior = Enum.MouseBehavior.Default end)
        local cam = Workspace.CurrentCamera
        if cam then
            cam.CameraType = Enum.CameraType.Custom
            local h = hum(); if h then cam.CameraSubject = h end
        end
    end
    local function start()
        local cam = Workspace.CurrentCamera
        if not cam then return end
        fc.on = true
        fc.pos = cam.CFrame.Position
        local rx, ry = cam.CFrame:ToEulerAnglesYXZ()
        fc.pitch, fc.yaw = rx, ry
        cam.CameraType = Enum.CameraType.Scriptable
        pcall(function() CAS:BindActionAtPriority("CW_Freecam", function() return Enum.ContextActionResult.Sink end, false, Enum.ContextActionPriority.High.Value + 100, table.unpack(keys)) end)
    end
    local fkey = HttpService:GenerateGUID(false)
    RunService:BindToRenderStep(fkey, Enum.RenderPriority.Last.Value, function(dt)
        if not (RUNNING and on("wd_freecam")) then stop(); return end
        if not fc.on then start() end
        local cam = Workspace.CurrentCamera
        if not cam then return end
        cam.CameraType = Enum.CameraType.Scriptable
        if UserInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
            UserInputService.MouseBehavior = Enum.MouseBehavior.LockCurrentPosition
            local d = UserInputService:GetMouseDelta()
            fc.yaw = fc.yaw - d.X * 0.005
            fc.pitch = math.clamp(fc.pitch - d.Y * 0.005, -1.5, 1.5)
        elseif UserInputService.MouseBehavior == Enum.MouseBehavior.LockCurrentPosition then
            UserInputService.MouseBehavior = Enum.MouseBehavior.Default
        end
        local mv = Vector3.zero
        if not UserInputService:GetFocusedTextBox() then
            local function k(a, b) return UserInputService:IsKeyDown(a) or (b and UserInputService:IsKeyDown(b)) end
            if k(Kc.W, Kc.Up) then mv = mv + Vector3.new(0, 0, -1) end
            if k(Kc.S, Kc.Down) then mv = mv + Vector3.new(0, 0, 1) end
            if k(Kc.A, Kc.Left) then mv = mv + Vector3.new(-1, 0, 0) end
            if k(Kc.D, Kc.Right) then mv = mv + Vector3.new(1, 0, 0) end
            if k(Kc.E, Kc.Space) then mv = mv + Vector3.new(0, 1, 0) end
            if k(Kc.Q) then mv = mv + Vector3.new(0, -1, 0) end
        end
        local rot = CFrame.fromEulerAnglesYXZ(fc.pitch, fc.yaw, 0)
        local spd = val("wd_fcspeed", 40) * (UserInputService:IsKeyDown(Kc.LeftShift) and 3 or 1)
        if mv.Magnitude > 0 then fc.pos = fc.pos + rot:VectorToWorldSpace(mv.Unit) * spd * (dt or 0.016) end
        cam.CFrame = CFrame.new(fc.pos) * rot
    end)
    onClean(function() pcall(function() RunService:UnbindFromRenderStep(fkey) end); stop() end)
end
do
    local MS = game:GetService("MarketplaceService")
    _G.__KE_HOOK = {
        MS = MS,
        hit = K.rem("ArenaHit"),
        buy = { [K.rem("Purchase") or 0] = true, [K.rem("BuyTrailRobux") or 0] = true, [K.rem("GiftPurchase") or 0] = true, [K.rem("ArenaSkip") or 0] = true },
        god = function() return RUNNING and on("ar_on") and on("ar_god") end,
        block = function() return RUNNING and on("pr_robux") end,
    }
    onClean(function() if _G.__KE_HOOK then _G.__KE_HOOK.god = function() return false end; _G.__KE_HOOK.block = function() return false end end end)
    local hid = false
    local function promptApp() local ok, cg = pcall(function() return game:GetService("CoreGui") end); return ok and cg and cg:FindFirstChild("PurchasePromptApp") end
    task.spawn(function()
        while RUNNING do
            local app = promptApp()
            if app then
                if on("pr_robux") then
                    if app.Enabled then pcall(function() app.Enabled = false end); hid = true end
                elseif hid then
                    pcall(function() app.Enabled = true end); hid = false
                end
            end
            task.wait(0.2)
        end
    end)
    onClean(function() local app = promptApp(); if app and hid then pcall(function() app.Enabled = true end) end end)
    if hookmetamethod and not _G.__KE_HOOKED then
        local blockM = { PromptProductPurchase = true, PromptGamePassPurchase = true, PromptPurchase = true, PromptBundlePurchase = true, PromptSubscriptionPurchase = true }
        local old
        old = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
            local H = _G.__KE_HOOK
            if H and not checkcaller() then
                local m = getnamecallmethod()
                if m == "FireServer" and self == H.hit and H.god() then K.arena.blocked = K.arena.blocked + 1; return nil end
                if H.buy[self] and (m == "FireServer" or m == "InvokeServer") and H.block() then return nil end
                if self == H.MS and blockM[m] and H.block() then return nil end
            end
            return old(self, ...)
        end))
        _G.__KE_HOOKED = true
    end
end
do
    local atk = K.rem("ArenaAttack")
    if atk then
        track(atk.OnClientEvent:Connect(function(p)
            if type(p) ~= "table" or not (on("ar_on") and on("ar_dodge")) then return end
            K.arena.attacks = K.arena.attacks + 1
            local wait = math.max(0, (tonumber(p.resolve) or now()) - now()) + 0.3
            task.delay(wait, function()
                if RUNNING and attr("ArenaFighting") == true then K.fire("ArenaDodge", p.id); K.arena.dodges = K.arena.dodges + 1 end
            end)
        end))
    end
    local res = K.rem("ArenaResult")
    if res then
        track(res.OnClientEvent:Connect(function(p)
            if type(p) == "table" and p.killed then S.dragons = S.dragons + 1; say(L["Dragon slain \194\183 +"] .. tostring(p.dragonSpirit or 0) .. L[" dragon spirit"]) end
        end))
    end
end
task.spawn(function()
    local lastFrame = os.clock()
    track(RunService.RenderStepped:Connect(function()
        if on("pf_cap") then
            local target = 1 / val("pf_fps", 30)
            while os.clock() - lastFrame < target do end
        end
        lastFrame = os.clock()
    end))
end)
task.spawn(K.moveBrain)
task.spawn(K.strikeLoop)
task.spawn(K.econLoop)
task.spawn(K.rateLoop)
task.spawn(function()
    while RUNNING do
        if on("mv_bar") then pcall(PL.barriers, true) end
        task.wait(5)
    end
end)
task.spawn(function()
    while RUNNING do
        if getgenv().Library ~= Library then getgenv().Library = Library end
        local txt = S.task or L["Idle"]
        if os.clock() - S.msgAt < 4 then txt = S.msg end
        setText(UI.status, txt)
        setText(UI.stats1, string.format(L["Spirit %s \194\183 +%s/s"], short(attr("Spirit", 0)), short(K.rate.spirit)))
        setText(UI.stats2, string.format(L["Wins %s \194\183 +%s/min"], short(attr("Wins", 0)), short(K.rate.wins * 60)))
        local n, st = nil, nil
        if K.GC then n, st = K.nextMaster() end
        local nxt = st and string.format(L["Master %d needs %s"], n, short((st.Spirit or 0) * val("ms_ratio", 80) / 100)) or L["All masters beaten"]
        setText(UI.stats3, string.format(L["Rebirths %s \194\183 Belt %s \194\183 %s"], tostring(attr("Rebirths", 0)), tostring(attr("BeltTier", 0)), nxt))
        do
            local ph = ReplicatedStorage:GetAttribute("LiveArenaEventPhase")
            local d
            if ph == "gather" then d = L["Dragon landed \194\183 joining"]
            elseif ph == "fight" then d = string.format(L["Dragon fight \194\183 %s/%s HP"], short(ReplicatedStorage:GetAttribute("ArenaHP") or 0), short(ReplicatedStorage:GetAttribute("ArenaMaxHP") or 0))
            elseif ph == "ending" then d = L["Dragon slain"]
            else
                local left = (tonumber(ReplicatedStorage:GetAttribute("NextArenaEventAt")) or 0) - now()
                if left > 0 then d = string.format(L["Next dragon in %d:%02d"], math.floor(left / 60), math.floor(left % 60)) else d = L["Dragon arriving"] end
            end
            setText(UI.dragon, d)
        end
        task.wait(0.5)
    end
end)
pcall(function() SaveManager:LoadAutoloadConfig() end)
PF.ready = true
task.spawn(function() if on("pf_on") then PF.apply() end end)
notify(L["Loaded"])

end
